import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { BaseRepository } from '../../core/database/base.repository';
import { DealEntity } from './deal.entity';
import { DealListQueryDto } from './dto';

@Injectable()
export class DealRepository extends BaseRepository<DealEntity> {
  constructor(dataSource: DataSource) {
    super(DealEntity, dataSource.createEntityManager());
  }

  async findWithFilter(query: DealListQueryDto) {
    const page = query.page ?? 1;
    const pageSize = query.pageSize ?? 10;

    const queryBuilder = this.createQueryBuilder('deal');

    if (query.stage) {
      queryBuilder.andWhere('deal.stage = :stage', { stage: query.stage });
    }

    if (query.companyId) {
      queryBuilder.andWhere('deal.companyId = :companyId', {
        companyId: query.companyId,
      });
    }

    const [items, total] = await queryBuilder
      .orderBy('deal.createdAt', 'DESC')
      .skip((page - 1) * pageSize)
      .take(pageSize)
      .getManyAndCount();

    return {
      items,
      total,
      page,
      pageSize,
      totalPages: total === 0 ? 0 : Math.ceil(total / pageSize),
    };
  }
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactService } from '../contact/contact.module';
import { CreateDealDto, DealListQueryDto, UpdateDealDto } from './dto';
import { DealEntity } from './deal.entity';
import { DealRepository } from './deal.repository';

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealEntity> {
    await this.assertCompanyExists(dto.companyId);
    await this.assertContactValidForCompany({
      companyId: dto.companyId,
      contactId: dto.contactId,
    });

    const deal = this.dealRepository.create({
      ...dto,
      contactId: dto.contactId ?? null,
      expectedCloseDate: dto.expectedCloseDate ?? null,
    });

    return await this.dealRepository.save(deal);
  }

  async getDeals(query: DealListQueryDto) {
    return await this.dealRepository.findWithFilter(query);
  }

  async getDealById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw this.createNotFoundException({
        resource: 'Deal',
        id,
        message: `Deal with ID ${id} not found`,
      });
    }

    return deal;
  }

  async getDealWithCompany(id: string) {
    const deal = await this.getDealById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);

    return {
      ...deal,
      company: {
        id: company.id,
        name: company.name,
      },
    };
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealEntity> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const deal = await this.getDealById(id);

    if (dto.contactId !== undefined) {
      await this.assertContactValidForCompany({
        companyId: deal.companyId,
        contactId: dto.contactId,
      });
    }

    const updatedDeal = this.dealRepository.merge(deal, dto);

    return await this.dealRepository.save(updatedDeal);
  }

  private async assertCompanyExists(companyId: string) {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (this.isNotFoundError(error)) {
        throw this.createNotFoundException({
          resource: 'Company',
          id: companyId,
          message: `Company with ID ${companyId} not found`,
        });
      }

      throw error;
    }
  }

  private async assertContactValidForCompany(input: {
    companyId: string;
    contactId: string | null | undefined;
  }) {
    const { companyId, contactId } = input;

    if (contactId === undefined || contactId === null) {
      return;
    }

    try {
      const contact = await this.contactService.getContactById(contactId);

      if (contact.companyId !== companyId) {
        throw this.createNotFoundException({
          resource: 'Contact',
          id: contactId,
          message: `Contact with ID ${contactId} not found`,
        });
      }
    } catch (error) {
      if (this.isNotFoundError(error)) {
        throw this.createNotFoundException({
          resource: 'Contact',
          id: contactId,
          message: `Contact with ID ${contactId} not found`,
        });
      }

      throw error;
    }
  }

  private createNotFoundException(input: {
    resource: 'Deal' | 'Company' | 'Contact';
    id: string;
    message: string;
  }) {
    const { resource, id, message } = input;

    return new AppException({
      statusCode: HttpStatus.NOT_FOUND,
      code: BUSINESS_ERROR_CODES.NOT_FOUND,
      message,
      details: {
        resource,
        id,
      },
    });
  }

  private isNotFoundError(error: unknown): boolean {
    return error instanceof AppException && error.getStatus() === 404;
  }
}
