export * from './create.dto';
export * from './update.dto';
export * from './query.dto';
export * from './create.dto';
export * from './query.dto';
export * from './update.dto';

const API_BASE_PATH = '/api';

// Thrown by request() for both network failures (status undefined) and non-2xx
// HTTP responses (status set). isTransportError() below is the single source of
// truth for "infra-level failure the global interceptor should toast" vs.
// "business error the calling page should handle and display itself".
export class RequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'RequestError';
    this.status = status;
  }
}

// Network failures (fetch itself rejected, no HTTP response at all) and 5xx
// server errors aren't meaningful to a specific page/action, so the global
// interceptor (see App.jsx) shows a generic toast for these. Every other
// status (400/401/403/404/409/422/...) is treated as a business error and
// left to the calling component to interpret and display.
export function isTransportError(error) {
  return !error?.status || error.status >= 500;
}

function buildUrl(path, query) {
  const url = new URL(`${API_BASE_PATH}${path}`, window.location.origin);

  if (query) {
    Object.entries(query).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        url.searchParams.set(key, value);
      }
    });
  }

  return `${url.pathname}${url.search}`;
}

// vite.config.js proxies /api/* to CRM_BASELINE_API_ORIGIN (backend mounts everything
// under app.setGlobalPrefix('api')), so callers pass paths like '/companies' and this
// prepends the /api prefix + serializes the `query` object as a querystring.
export async function request(path, { query, headers, ...options } = {}) {
  let response;

  try {
    response = await fetch(buildUrl(path, query), {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
    });
  } catch {
    throw new RequestError('Network error, please check your connection and try again.', undefined);
  }

  const text = await response.text();
  const data = text ? JSON.parse(text) : null;

  if (!response.ok) {
    const message = data?.message || response.statusText || 'Request failed';
    throw new RequestError(Array.isArray(message) ? message.join(', ') : message, response.status);
  }

  return data;
}

import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const EDGE_PREFIX = 'Edge Seed Company';
const EDGE_DEAL_PREFIX = 'Edge Seed Deal';

const MAX_COMPANY_NAME = `${EDGE_PREFIX} Long Name ${'X'.repeat(225)}`.slice(
  0,
  255,
);
const MAX_CONTACT_ROLE = `Role-${'Y'.repeat(95)}`.slice(0, 100);
const EDGE_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-lost',
] as const;

export const edgeCaseSeedScenario: SeedScenario = {
  name: 'edge-case',
  async run({ dataSource, now }) {
    const companyRepository = dataSource.getRepository(CompanyEntity);
    const contactRepository = dataSource.getRepository(ContactEntity);
    const dealRepository = dataSource.getRepository(DealEntity);

    await cleanupCompaniesByPrefixes({ dataSource, now }, [EDGE_PREFIX]);

    const companies = [
      buildCompany({
        name: `${EDGE_PREFIX} 00 Empty Contacts`,
        status: CompanyStatus.PENDING,
        email: null,
        phone: null,
        website: null,
      }),
      buildCompany({
        name: `${EDGE_PREFIX} 01 Missing Fields`,
        status: CompanyStatus.INACTIVE,
        email: null,
        phone: null,
        website: null,
        lastContactedAt: distributeRecentDate(now, 1, 25),
      }),
      buildCompany({
        name: MAX_COMPANY_NAME,
        status: CompanyStatus.ACTIVE,
        industry: Industry.TECHNOLOGY,
        lastContactedAt: distributeRecentDate(now, 2, 25),
      }),
      ...Array.from({ length: 22 }, (_, index) =>
        buildCompany({
          name: `${EDGE_PREFIX} ${String(index + 2).padStart(2, '0')} ${['Alpha', 'Sort', 'Filter', 'Pagination'][index % 4]} ${String(index + 1).padStart(2, '0')}`,
          status: [
            CompanyStatus.ACTIVE,
            CompanyStatus.INACTIVE,
            CompanyStatus.PENDING,
          ][index % 3],
          industry: [
            Industry.FINANCE,
            Industry.MANUFACTURING,
            Industry.RETAIL,
            Industry.OTHER,
          ][index % 4],
          email:
            index % 5 === 0 ? null : `edge-company-${index + 1}@baseline.local`,
          phone:
            index % 6 === 0
              ? null
              : `+1-415-55${String(index).padStart(2, '0')}`,
          website:
            index % 7 === 0
              ? null
              : `https://edge-company-${index + 1}.baseline.local`,
          lastContactedAt: distributeRecentDate(now, index + 3, 25),
        }),
      ),
    ];

    const savedCompanies = await companyRepository.save(
      companies.map((company) => companyRepository.create(company)),
    );

    let contactsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex === 0) {
        continue;
      }

      const contactsForCompany = companyIndex === 1 ? 1 : 1 + (companyIndex % 3);

      for (
        let contactIndex = 0;
        contactIndex < contactsForCompany;
        contactIndex += 1
      ) {
        contactsCreated += 1;

        await contactRepository.save(
          contactRepository.create(
            buildContact({
              companyId: company.id,
              name:
                companyIndex === 2 && contactIndex === 0
                  ? `Contact ${'Z'.repeat(240)}`.slice(0, 255)
                  : `${['Alpha', 'Beta', 'Gamma', 'Omega'][contactIndex % 4]} Edge Contact ${companyIndex}-${contactIndex}`,
              email:
                contactIndex % 4 === 0
                  ? null
                  : `edge-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
              phone:
                contactIndex % 5 === 0
                  ? null
                  : `+1-628-44${companyIndex}${contactIndex}`,
              role:
                companyIndex === 2 && contactIndex === 0
                  ? MAX_CONTACT_ROLE
                  : ['Evaluator', 'Technical Buyer', 'Influencer'][
                      contactIndex % 3
                    ],
              lastContactedAt:
                companyIndex % 6 === 0 && contactIndex === 0
                  ? undefined
                  : distributeRecentDate(now, companyIndex + contactIndex, 40),
            }),
          ),
        );
      }
    }

    let dealsCreated = 0;

    for (const [companyIndex, company] of savedCompanies.entries()) {
      if (companyIndex >= 10) {
        break;
      }

      const contacts = await contactRepository.find({
        where: { companyId: company.id },
        order: { createdAt: 'ASC' },
      });

      const expectedCloseDate =
        companyIndex % 4 === 1
          ? null
          : new Date(
              Date.UTC(
                now.getUTCFullYear(),
                now.getUTCMonth(),
                now.getUTCDate() + 14 + companyIndex,
              ),
            )
              .toISOString()
              .slice(0, 10);

      await dealRepository.save(
        dealRepository.create(
          buildDeal({
            name: `${EDGE_DEAL_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`,
            value: 5000 + companyIndex * 1700,
            companyId: company.id,
            stage: EDGE_STAGES[companyIndex % EDGE_STAGES.length],
            contactId:
              companyIndex % 3 === 0 ? null : (contacts[0]?.id ?? null),
            expectedCloseDate,
          }),
        ),
      );

      dealsCreated += 1;
    }

    return {
      scenario: 'edge-case',
      companiesCreated: savedCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Includes one company with zero contacts for empty-state testing.',
        'Creates 25 companies to exercise pagination and sorting.',
        'Adds null fields and max-length values for form, table, and deal edge cases.',
      ],
    };
  },
};

import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_COMPANY_PREFIX = 'Demo Seed Company';
const DEMO_DEAL_PREFIX = 'Demo Seed Deal';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const createdCompanies: DemoCompanyRecord[] = [];
  let contactsCreated = 0;

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_COMPANY_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_COMPANY_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactIds: string[] = [];
    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            companyId: company.id,
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      contactIds.push(contact.id);
    }

    createdCompanies.push({ company, contactIds });
  }

  return {
    createdCompanies,
    contactsCreated,
  };
};

const createDemoDeals = async (
  { dataSource, now }: SeedContext,
  companies: DemoCompanyRecord[],
) => {
  const dealRepository = dataSource.getRepository(DealEntity);
  let dealsCreated = 0;

  for (const [index, record] of companies.entries()) {
    const expectedCloseDate =
      index % 4 === 0
        ? null
        : new Date(
            Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()),
          );

    if (expectedCloseDate) {
      expectedCloseDate.setUTCDate(expectedCloseDate.getUTCDate() + 21 + index * 3);
    }

    await dealRepository.save(
      dealRepository.create(
        buildDeal({
          name: `${DEMO_DEAL_PREFIX} ${String(index + 1).padStart(2, '0')}`,
          value: 15000 + index * 4000,
          companyId: record.company.id,
          stage: DEAL_STAGES[index % DEAL_STAGES.length],
          contactId: index % 3 === 0 ? null : (record.contactIds[0] ?? null),
          expectedCloseDate: expectedCloseDate
            ? expectedCloseDate.toISOString().slice(0, 10)
            : null,
        }),
      ),
    );

    dealsCreated += 1;
  }

  return dealsCreated;
};

export const demoSeedScenario: SeedScenario = {
  name: 'demo',
  async run(context) {
    faker.seed(20260703);

    const { createdCompanies, contactsCreated } = await createDemoCompanies(context);
    const dealsCreated = await createDemoDeals(context, createdCompanies);

    return {
      scenario: 'demo',
      companiesCreated: createdCompanies.length,
      contactsCreated,
      dealsCreated,
      notes: [
        'Creates 10 companies with 2-5 contacts each.',
        'Creates 10 deals across five pipeline stages.',
        'Distributes lastContactedAt timestamps across the last 30 days.',
      ],
    };
  },
};

