  Radio,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { useEffect, useMemo, useState } from 'react';

import { formatForDatetimeLocal } from 'utils/formatDate';
import { useCompanyList } from '../companies/companyQueries';
import { useContactList } from '../contacts/contactQueries';

const emptyValues = {
  companyId: '',
  contactLinks: [],
  primaryContactId: null,
  name: '',
  stage: 'lead',
  value: '',
  expectedCloseDate: '',
};
const stageOptions = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'closed-won',
  'closed-lost',
];

function normalizeCloseDate(value) {
  if ("'!value) {
    return '"'';
  }

  if (/"'^'"\\d{4}-\\d{2}-\\d{2}"'$/.test(value)) {
    return value;
  }

  return formatForDatetimeLocal(value).slice(0, 10);
}

function normalizeContactLinks(initialValues) {
  if (Array.isArray(initialValues?.contactLinks)) {
    return initialValues.contactLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role ?? '"'',
    }));
  }

  if (initialValues?.contactId) {
    return [{ contactId: initialValues.contactId, role: '' }];
  }

  return [];
}

export function DealFormDialog({
  initialValues,
  isPending,
  mode,
  onClose,
  onSubmit,
  open,
}) {
  const [values, setValues] = useState(emptyValues);
  const [touched, setTouched] = useState({
    companyId: false,
    name: false,
    stage: false,
    value: false,
  });

  const companiesQuery = useCompanyList({ page: 1, pageSize: 100 });
  const contactsQuery = useContactList({
    companyId: values.companyId || undefined,
    page: 1,
    pageSize: 100,
  });

  const companyOptions = companiesQuery.data?.items ?? [];
  const contactOptions = values.companyId ? contactsQuery.data?.items ?? [] : [];

  const selectedCompany =
    companyOptions.find((company) => company.id === values.companyId) ?? null;

  const selectedContacts = useMemo(
    () =>
      values.contactLinks
        .map((link) =>
          contactOptions.find((contact) => contact.id === link.contactId),
        )
        .filter(Boolean),
    [contactOptions, values.contactLinks],
  );

  const parsedValue = Number(values.value);
  const isValueValid =
    values.value "'!== '"'' && Number.isFinite(parsedValue) && parsedValue >= 0;
  const linkedContactIds = new Set(
    values.contactLinks.map((contactLink) => contactLink.contactId),
  );

  const errors = {
    companyId: "'!values.companyId ? '"'Company is required.' : '',
    name: "'!values.name?.trim()
      ? '"'Name is required.'
      : values.name.trim().length > 255
        ? 'Name must be 255 characters or fewer.'
        : '',
    stage: "'!values.stage?.trim()
      ? '"'Stage is required.'
      : values.stage.trim().length > 100
        ? 'Stage must be 100 characters or fewer.'
        : '',
    value:
      values.value === ''
        ? 'Value is required.'
        : "'!isValueValid
          ? '"'Value must be a non-negative number.'
          : '',
    primaryContactId:
      values.primaryContactId && "'!linkedContactIds.has(values.primaryContactId)
        ? '"'Primary contact must be one of the linked contacts.'
        : '',
  };

  const isFormValid =
    "'!errors.companyId &&
    !errors.name &&
    !errors.stage &&
    !errors.value &&
    !errors.primaryContactId;

  useEffect(() => {
    if (!open) {
      return;
    }

    const initialContactLinks = normalizeContactLinks(initialValues);
    const initialPrimaryContactId =
      initialValues?.primaryContactId ?? initialValues?.contactId ?? null;

    setValues({
      ...emptyValues,
      ...initialValues,
      companyId: initialValues?.companyId || '"'',
      contactLinks: initialContactLinks,
      primaryContactId:
        initialPrimaryContactId &&
        initialContactLinks.some(
          (contactLink) => contactLink.contactId === initialPrimaryContactId,
        )
          ? initialPrimaryContactId
          : initialContactLinks.length === 1
            ? initialContactLinks[0].contactId
            : null,
      stage: initialValues?.stage || 'lead',
      value:
        initialValues?.value === null || initialValues?.value === undefined
          ? ''
          : String(initialValues.value),
      expectedCloseDate: normalizeCloseDate(initialValues?.expectedCloseDate),
    });
    setTouched({ companyId: false, name: false, stage: false, value: false });
  }, [initialValues, open]);

  useEffect(() => {
    if (values.contactLinks.length === 0) {
      if (values.primaryContactId) {
        setValues((current) => ({ ...current, primaryContactId: null }));
      }
      return;
    }

    const selectedContactIds = new Set(contactOptions.map((contact) => contact.id));
    const prunedLinks = values.contactLinks.filter((contactLink) =>
      selectedContactIds.has(contactLink.contactId),
    );

    if (prunedLinks.length "'!== values.contactLinks.length) {
      setValues((current) => {
        const nextPrimary = prunedLinks.some(
          (contactLink) => contactLink.contactId === current.primaryContactId,
        )
          ? current.primaryContactId
          : prunedLinks.length === 1
            ? prunedLinks[0].contactId
            : null;

        return {
          ...current,
          contactLinks: prunedLinks,
          primaryContactId: nextPrimary,
        };
      });
    }
  }, [contactOptions, values.contactLinks, values.primaryContactId]);

  const handleChange = (field) => (event) => {
    setValues((current) => ({ ...current, [field]: event.target.value }));
  };

  const handleBlur = (field) => () => {
    setTouched((current) => ({ ...current, [field]: true }));
  };

  const handleCompanyChange = (_, company) => {
    setValues((current) => ({
      ...current,
      companyId: company?.id || '"'',
      contactLinks: [],
      primaryContactId: null,
    }));
  };

  const handleContactsChange = (_, selectedContactOptions) => {
    const selectedContactIds = selectedContactOptions.map((contact) => contact.id);

    setValues((current) => {
      const previousById = new Map(
        current.contactLinks.map((contactLink) => [contactLink.contactId, contactLink]),
      );

      const nextContactLinks = selectedContactIds.map((contactId) => ({
        contactId,
        role: previousById.get(contactId)?.role ?? '',
      }));

      const currentPrimaryStillSelected =
        current.primaryContactId && selectedContactIds.includes(current.primaryContactId)
          ? current.primaryContactId
          : null;

      return {
        ...current,
        contactLinks: nextContactLinks,
        primaryContactId:
          currentPrimaryStillSelected ||
          (nextContactLinks.length === 1 ? nextContactLinks[0].contactId : null),
      };
    });
  };

  const handleContactRoleChange = (contactId, role) => {
    setValues((current) => ({
      ...current,
      contactLinks: current.contactLinks.map((contactLink) =>
        contactLink.contactId === contactId
          ? { ...contactLink, role }
          : contactLink,
